import * as THREE from 'three';
import { createScene } from './data/object.js';
import * as fs from 'fs';

// Create the scene from the original Three.js file
const root = createScene();

// Apply -90 degrees X-rotation to convert from Three.js Y-up to Blender Z-up
const rotationMatrix = new THREE.Matrix4();
rotationMatrix.makeRotationX(-Math.PI / 2);

// Function to get world vertices from a BufferGeometry with transforms applied
function getWorldVertices(mesh, worldMatrix) {
  const geometry = mesh.geometry;
  const position = geometry.getAttribute('position');
  const vertices = [];

  for (let i = 0; i < position.count; i++) {
    const vertex = new THREE.Vector3(
      position.getX(i),
      position.getY(i),
      position.getZ(i)
    );
    vertex.applyMatrix4(worldMatrix);
    // Apply the coordinate system rotation
    vertex.applyMatrix4(rotationMatrix);
    vertices.push(vertex);
  }

  return vertices;
}

// Function to get faces from a BufferGeometry
function getFaces(geometry) {
  const faces = [];
  const index = geometry.getIndex();

  if (index) {
    // Indexed geometry
    for (let i = 0; i < index.count; i += 3) {
      faces.push([
        index.getX(i),
        index.getX(i + 1),
        index.getX(i + 2)
      ]);
    }
  } else {
    // Non-indexed geometry
    const position = geometry.getAttribute('position');
    for (let i = 0; i < position.count; i += 3) {
      faces.push([i, i + 1, i + 2]);
    }
  }

  return faces;
}

// Collect all meshes with their world transforms
const meshData = [];

root.traverse((object) => {
  if (object.isMesh) {
    object.updateWorldMatrix(true, false);

    if (object.isInstancedMesh) {
      // Handle InstancedMesh - expand each instance as a separate mesh
      const instanceMatrix = new THREE.Matrix4();
      for (let i = 0; i < object.count; i++) {
        object.getMatrixAt(i, instanceMatrix);
        const combinedMatrix = new THREE.Matrix4();
        combinedMatrix.multiplyMatrices(object.matrixWorld, instanceMatrix);

        meshData.push({
          name: `${object.name}_instance_${i}`,
          geometry: object.geometry,
          worldMatrix: combinedMatrix.clone()
        });
      }
    } else {
      meshData.push({
        name: object.name,
        geometry: object.geometry,
        worldMatrix: object.matrixWorld.clone()
      });
    }
  }
});

// Build OBJ file content
let objContent = '# Exported from Three.js\n';
objContent += '# Converted to Blender Z-up coordinate system\n\n';

let vertexOffset = 0;

for (const data of meshData) {
  const { name, geometry, worldMatrix } = data;

  objContent += `# Object: ${name}\n`;
  objContent += `o ${name}\n`;

  // Get world-transformed vertices
  const position = geometry.getAttribute('position');
  for (let i = 0; i < position.count; i++) {
    const vertex = new THREE.Vector3(
      position.getX(i),
      position.getY(i),
      position.getZ(i)
    );
    vertex.applyMatrix4(worldMatrix);
    vertex.applyMatrix4(rotationMatrix);
    objContent += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
  }

  // Get faces
  const faces = getFaces(geometry);
  for (const face of faces) {
    // OBJ indices are 1-based
    const i1 = face[0] + vertexOffset + 1;
    const i2 = face[1] + vertexOffset + 1;
    const i3 = face[2] + vertexOffset + 1;
    objContent += `f ${i1} ${i2} ${i3}\n`;
  }

  objContent += '\n';
  vertexOffset += position.count;
}

// Write the OBJ file
fs.writeFileSync('/root/output/object.obj', objContent);
console.log('Successfully exported to /root/output/object.obj');
console.log(`Total meshes exported: ${meshData.length}`);

